using UnityEngine;
using UnityEngine.UI;
namespace ProjectTweenKit {
public sealed partial class VictoryPresentation {
 readonly RectTransform[] headerStars=new RectTransform[3];readonly Vector2[] headerFrom=new Vector2[3],headerSizes=new Vector2[3];readonly float[] headerAngles=new float[3];
 public RectTransform[] HeaderStars=>headerStars;
 void BuildHeaderStars(){for(int i=0;i<3;i++){headerStars[i]=BattleJellyArt.Image(transform,"vine-star-on",(i-1)*270,i==1?365:230,310,310).rectTransform;headerFrom[i]=headerStars[i].anchoredPosition;headerSizes[i]=Vector2.one*310;headerAngles[i]=(i-1)*-12;}}
 public void ReceiveVictoryStars(RectTransform[] actual){for(int i=0;i<3&&i<actual.Length;i++){if(headerStars[i]!=null){headerStars[i].gameObject.SetActive(false);Destroy(headerStars[i].gameObject);}var star=actual[i];Vector2 position=transform.InverseTransformPoint(star.position);var size=Vector2.Scale(star.rect.size,new Vector2(star.lossyScale.x/transform.lossyScale.x,star.lossyScale.y/transform.lossyScale.y));float angle=star.eulerAngles.z;star.SetParent(transform,false);var face=star.GetComponent<Image>();face.enabled=false;face.material=null;face.sprite=BattleJellyArt.Get("vine-star-off");face.color=new Color(.76f,.94f,.64f,1);face.canvasRenderer.SetAlpha(1);face.enabled=true;face.SetAllDirty();star.localScale=Vector3.one;headerStars[i]=star;headerFrom[i]=position;headerSizes[i]=size;headerAngles[i]=angle;star.SetAsLastSibling();}RenderHeaderStars(true);}
 void RenderHeaderStars(bool motion){float p=motion?Mathf.Clamp01((clock-.08f)/.8f):1;float move=1-Mathf.Pow(1-p,3);for(int i=0;i<3;i++){var star=headerStars[i];if(star==null)continue;var end=new Vector2((i-1)*250,i==1?740:625);var size=Vector2.one*(i==1?207:184);star.anchoredPosition=Vector2.Lerp(headerFrom[i],end,move);star.sizeDelta=Vector2.Lerp(headerSizes[i],size,move);star.localRotation=Quaternion.Euler(0,0,Mathf.LerpAngle(headerAngles[i],(i-1)*-10,move));star.GetComponent<StarChargeView>()?.RefreshGeometry(KitClock.Delta);float idle=Mathf.Max(0,clock-.88f);float blend=motion?Mathf.SmoothStep(0,1,Mathf.Clamp01(idle/.25f)):0;star.anchoredPosition+=JellyMotion.FloatOffset(idle,i)*blend;star.localScale=Vector3.Lerp(Vector3.one*(1+Mathf.Sin(p*Mathf.PI)*.08f),JellyMotion.FloatScale(idle,i),blend);star.localRotation*=Quaternion.Euler(0,0,JellyMotion.FloatAngle(idle,i)*blend);}}
}
}
